/// Accent and group characters to a LaTeX command taking one braced argument (`CHR` table).
pub fn accent(c: char) -> Option<&'static str> {
    Some(match c {
        '\u{300}' => "\\grave",
        '\u{301}' => "\\acute",
        '\u{302}' => "\\hat",
        '\u{303}' => "\\tilde",
        '\u{304}' => "\\bar",
        '\u{305}' => "\\overbar",
        '\u{306}' => "\\breve",
        '\u{307}' => "\\dot",
        '\u{308}' => "\\ddot",
        '\u{309}' => "\\ovhook",
        '\u{30a}' => "\\ocirc",
        '\u{30c}' => "\\check",
        '\u{310}' => "\\candra",
        '\u{312}' => "\\oturnedcomma",
        '\u{315}' => "\\ocommatopright",
        '\u{31a}' => "\\droang",
        '\u{338}' => "\\not",
        '\u{20d0}' => "\\leftharpoonaccent",
        '\u{20d1}' => "\\rightharpoonaccent",
        '\u{20d2}' => "\\vertoverlay",
        '\u{20d6}' => "\\overleftarrow",
        '\u{20d7}' => "\\vec",
        '\u{20db}' => "\\dddot",
        '\u{20dc}' => "\\ddddot",
        '\u{20e1}' => "\\overleftrightarrow",
        '\u{20e7}' => "\\annuity",
        '\u{20e9}' => "\\widebridgeabove",
        '\u{20f0}' => "\\asteraccent",
        '\u{330}' => "\\wideutilde",
        '\u{331}' => "\\underbar",
        '\u{20e8}' => "\\threeunderdot",
        '\u{20ec}' => "\\underrightharpoondown",
        '\u{20ed}' => "\\underleftharpoondown",
        '\u{20ee}' => "\\underleftarrow",
        '\u{20ef}' => "\\underrightarrow",
        '\u{23b4}' => "\\overbracket",
        '\u{23dc}' => "\\overparen",
        '\u{23de}' => "\\overbrace",
        '\u{23b5}' => "\\underbracket",
        '\u{23dd}' => "\\underparen",
        '\u{23df}' => "\\underbrace",
        _ => return None,
    })
}

/// Big operator characters to a LaTeX command (`CHR_BO` table).
pub fn big_operator(c: char) -> Option<&'static str> {
    Some(match c {
        '\u{2140}' => "\\Bbbsum",
        '\u{220f}' => "\\prod",
        '\u{2210}' => "\\coprod",
        '\u{2211}' => "\\sum",
        '\u{222b}' => "\\int",
        '\u{22c0}' => "\\bigwedge",
        '\u{22c1}' => "\\bigvee",
        '\u{22c2}' => "\\bigcap",
        '\u{22c3}' => "\\bigcup",
        '\u{2a00}' => "\\bigodot",
        '\u{2a01}' => "\\bigoplus",
        '\u{2a02}' => "\\bigotimes",
        _ => return None,
    })
}

/// Function names with a dedicated LaTeX command (`FUNC` table), as the command text.
pub fn function(name: &str) -> Option<&'static str> {
    Some(match name {
        "sin" => "\\sin",
        "cos" => "\\cos",
        "tan" => "\\tan",
        "arcsin" => "\\arcsin",
        "arccos" => "\\arccos",
        "arctan" => "\\arctan",
        "arccot" => "\\operatorname{arccot}",
        "sinh" => "\\sinh",
        "cosh" => "\\cosh",
        "tanh" => "\\tanh",
        "coth" => "\\coth",
        "sec" => "\\sec",
        "csc" => "\\csc",
        "log" => "\\log",
        "ln" => "\\ln",
        "exp" => "\\exp",
        "det" => "\\det",
        "gcd" => "\\gcd",
        "lcm" => "\\operatorname{lcm}",
        "lim" => "\\lim",
        "max" => "\\max",
        "min" => "\\min",
        "sup" => "\\sup",
        "inf" => "\\inf",
        "dim" => "\\dim",
        "ker" => "\\ker",
        "hom" => "\\hom",
        "deg" => "\\deg",
        "arg" => "\\arg",
        _ => return None,
    })
}
